insert into source.source_entity (
    id, name, slug, entity_type, country_code, official_level, authority_score,
    website_url, logo_url, status, version, created_by
) values (
    #{id}, #{name}, #{slug}, #{entityType}, #{countryCode}, #{officialLevel}, #{authorityScore},
    #{websiteUrl}, #{logoUrl}, #{status}, #{version}, #{createdBy}
) on conflict (slug) do nothing

mapper.select:
select id, name, slug, entity_type, country_code, official_level, authority_score,
       website_url, logo_url, status, version, created_by, created_at, updated_at
from source.source_entity where id = #{id}

select s.id, s.name, s.slug, s.entity_type, s.official_level, s.authority_score, s.status as source_status, e.id as endpoint_id, e.name as endpoint_name, e.endpoint_type, e.connector_type, e.url as endpoint_url, e.status as endpoint_status, e.catalog_kind, e.health_status, e.last_success_at, e.last_failure_at, e.version as endpoint_version, e.last_fetch_item_count, (select count(*) from content.content_item c where c.endpoint_id = e.id and c.created_at >= date_trunc('day', now() at time zone 'Asia/Shanghai') at time zone 'Asia/Shanghai') as today_content_count, e.updated_at from source.source_entity s join source.source_endpoint e on e.source_entity_id = s.id
e.status = #{status}
and (s.name ilike '%' || #{query} || '%' or e.name ilike '%' || #{query} || '%' or e.normalized_url ilike '%' || #{query} || '%')
order by e.updated_at desc, e.id desc limit #{limit}

mapper.update:
update source.source_endpoint
set status = #{status}, version = version + 1, updated_at = now()
where id = #{id} and version = #{version}
